        float center = Sin(angle) * (1.0f - folded) * (1.0f - folded_copy) * 4.4444447f;
        ((PathTemplateSample*)((char*)primary_samples + curve_sample_offset))
            ->center_x = center;
        ((PathTemplateSample*)((char*)primary_samples + curve_sample_offset))
            ->rotation_scalar_98 = 0.0f;
        ((PathTemplateSample*)((char*)primary_samples + curve_sample_offset))
