            &((PathTemplateSample*)((char*)primary_samples + lead_sample_offset))
                ->transform);
        float z = (float)lead_sample_index;
        ((PathTemplateSample*)((char*)primary_samples + lead_sample_offset))
            ->transform.position.x =
            ((PathTemplateSample*)((char*)primary_samples + lead_sample_offset))
