        ((PathTemplateSample*)((char*)primary_samples + departure_sample_offset))
            ->transform.position.y = 0.0f;
        ((PathTemplateSample*)((char*)primary_samples + departure_sample_offset))
            ->transform.position.z = z;
        set_matrix_identity(
            &((PathTemplateSample*)((char*)secondary_samples + departure_sample_offset))
                ->transform);
        ((PathTemplateSample*)((char*)secondary_samples + departure_sample_offset))
            ->transform.position.x =
            ((PathTemplateSample*)((char*)primary_samples + departure_sample_offset))
